import { Router } from "express";
import { validateBody } from "../../middlewares/validate.middleware.js";
import { createBrandSchema, updateBrandSchema, } from "./brand.validation.js";
import { getBrands, getBrandById, createBrand, updateBrand, deactivateBrand, } from "./brand.controller.js";
const router = Router();
router.get("/", getBrands);
router.get("/:id", getBrandById);
router.post("/", validateBody(createBrandSchema), createBrand);
router.patch("/:id", validateBody(updateBrandSchema), updateBrand);
router.delete("/:id", deactivateBrand);
export default router;
